import base64
import hashlib
import json
import os
from pathlib import Path
from types import SimpleNamespace

import pytest

from sri_localcheck import core
from sri_localcheck.cli import main
from sri_localcheck.core import InputError, check, metadata

# Independently generated by Node crypto, also the standard SHA-2 "abc" vectors.
ABC = {
    "sha256": "ungWv48Bz+pBQUDeXa4iI7ADYaOWF3qctBD/YfIAFa0=",
    "sha384": "ywB1P0WjXou1oD1pmsZQBycsMqsO3tFjGotgWkP/W+2AhgcroefMI1i67KE0yCWn",
    "sha512": (
        "3a81oZNherrMQXNJriBBMRLm+k6JqX6iCp7u5ktV05ohkpkqJ0/BqDa6PCOj/uu9RU1EI2Q86A4qmslPpUyknw=="
    ),
}


def sri(data=b"abc", algorithm="sha384"):
    return algorithm + "-" + base64.b64encode(hashlib.new(algorithm, data).digest()).decode()


def script(value=None, url="app.js"):
    return f'<script src="{url}" integrity="{value or sri()}"></script>'


def site(folder, markup=None, files=None, document="index.html"):
    folder.mkdir(exist_ok=True)
    for name, data in (files or {"app.js": b"abc"}).items():
        path = folder / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
    path = folder / document
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(markup or script(), encoding="utf-8", newline="\n")
    return folder, Path(document)


def code(result):
    return result["checks"][0]["code"]


@pytest.mark.parametrize("algorithm", ABC)
def test_independent_abc_hash_vectors_and_immutable_sources(tmp_path, algorithm):
    args = site(tmp_path, script(f"{algorithm}-{ABC[algorithm]}"))
    original = {
        str(p.relative_to(tmp_path)): p.read_bytes() for p in tmp_path.rglob("*") if p.is_file()
    }
    result = check(*args)
    assert result["status"] == "pass" and result["asset_bytes_read"] == 3
    assert result["checks"][0]["algorithm"] == algorithm
    assert original == {
        str(p.relative_to(tmp_path)): p.read_bytes() for p in tmp_path.rglob("*") if p.is_file()
    }
    text = json.dumps(result)
    assert "app.js" not in text and str(tmp_path) not in text and ABC[algorithm] not in text


@pytest.mark.parametrize(
    "tokens,expected",
    [
        ([sri(algorithm="sha256"), sri(b"wrong", "sha512")], "integrity_mismatch"),
        ([sri(b"wrong", "sha256"), sri(algorithm="sha512")], "match"),
        ([sri(b"wrong", "sha384"), sri(algorithm="sha384")], "match"),
        ([sri(), sri(b"wrong", "sha384"), sri(b"wrong", "sha256")], "match"),
    ],
)
def test_strongest_metadata_and_same_strength_alternatives(tmp_path, tokens, expected):
    result = check(*site(tmp_path, script(" ".join(tokens))))
    assert code(result) == expected
    assert result["status"] == ("pass" if expected == "match" else "fail")


@pytest.mark.parametrize(
    "value",
    [
        "",
        " ",
        "sha1-YWJj",
        "sha384-bad",
        "sha384-!!!!",
        "SHA384-" + ABC["sha384"],
        "sha256-" + ABC["sha256"] + "=",
        "sha384-" + ABC["sha384"] + "?option",
        sri() + " sha999-unknown",
        "sha256-" + base64.b64encode(b"a" * 31).decode(),
        "sha256-" + ABC["sha256"][:-2] + "1=",
    ],
)
def test_strict_metadata_policy(value):
    with pytest.raises(InputError, match="invalid_integrity"):
        metadata(value)


def test_urlsafe_unpadded_and_ascii_whitespace_metadata():
    value = "\tsha256-" + ABC["sha256"].rstrip("=").replace("+", "-").replace("/", "_") + "\r\n"
    algorithm, candidates = metadata(value)
    assert algorithm == "sha256" and candidates == {hashlib.sha256(b"abc").digest()}


def test_local_base_root_paths_entities_and_utf8_names(tmp_path):
    markup = '<base href="../assets/">\n' + script(url="a%20b.js?version=1&amp;k=2#part")
    args = site(tmp_path, markup, {"assets/a b.js": b"abc"}, "pages/index.html")
    assert check(*args)["status"] == "pass"
    args = site(tmp_path, script(url="/assets/%E6%B5%8B%E8%AF%95.js"), {"assets/测试.js": b"abc"})
    assert check(*args)["status"] == "pass"
    args = site(tmp_path, script(url="../assets/a%20b.js"), document="pages/index.html")
    assert check(*args)["status"] == "pass"


@pytest.mark.parametrize(
    "url,expected",
    [
        ("https://private.example.test/secret.js?token=private", "unverified_external_url"),
        ("//cdn.example.test/app.js", "unverified_external_url"),
        ("file:///etc/passwd", "unverified_external_url"),
        ("data:text/javascript,secret", "unverified_external_url"),
        ("///cdn.example.test/a.js", "unverified_external_url"),
        ("%Q0.js", "invalid_url"),
        ("%FF.js", "invalid_url"),
        ("%00.js", "unsafe_path"),
        ("%2e%2e/secret", "unsafe_path"),
        ("app%5c.js", "unsafe_path"),
        ("app%3A.js", "unsafe_path"),
        ("a//b.js", "unsafe_path"),
        ("CON.js", "unsafe_path"),
        ("assets/trailing./a.js", "unsafe_path"),
        ("app\\x.js", "invalid_url"),
        ("app\tx.js", "invalid_url"),
        ("", "invalid_url"),
    ],
)
def test_url_rejection_and_diagnostic_redaction(tmp_path, url, expected):
    result = check(*site(tmp_path, script(url=url)))
    assert code(result) == expected
    assert result["asset_bytes_read"] == 0
    assert "private.example.test" not in json.dumps(result)
    assert "token=private" not in json.dumps(result)


@pytest.mark.parametrize(
    "base",
    [
        '<base href="https://example.test/">',
        '<base href="/a/"><base href="/b/">',
        '<base href="/a/" href="/b/">',
        "<base href>",
        '<base href="">',
    ],
)
def test_unverified_or_ambiguous_base_fails(tmp_path, base):
    result = check(*site(tmp_path, base + script()))
    assert code(result) in {"invalid_base", "unverified_base"}
    assert result["asset_bytes_read"] == 0


def test_stylesheet_script_and_attribute_ambiguity(tmp_path):
    args = site(tmp_path, f'<link REL="alternate stylesheet" href="app.js" integrity="{sri()}"/>')
    assert check(*args)["status"] == "pass"
    args = site(tmp_path, f'<script src="app.js" src="wrong.js" integrity="{sri()}"></script>')
    assert code(check(*args)) == "duplicate_attribute"
    args = site(tmp_path, f'<img src="app.js" integrity="{sri()}">')
    assert code(check(*args)) == "unsupported_integrity_element"
    args = site(tmp_path, f'<base href="/" integrity="{sri()}">')
    assert code(check(*args)) == "unsupported_integrity_element"


def test_require_integrity_and_no_vacuous_success(tmp_path):
    markup = '<script src="app.js"></script>' + script()
    args = site(tmp_path, markup)
    assert check(*args)["checked"] == 1
    result = check(*args, require_integrity=True)
    assert result["checked"] == 2 and result["failed"] == 1
    assert code(result) == "missing_integrity"
    args = site(tmp_path, '<script src="app.js"></script>')
    with pytest.raises(InputError, match="no_applicable_declarations"):
        check(*args)
    assert code(check(*args, require_integrity=True)) == "missing_integrity"
    args = site(tmp_path, '<!-- <script src="ignored" integrity="bad"></script> -->')
    with pytest.raises(InputError, match="no_applicable_declarations"):
        check(*args)


def test_cache_preserves_per_declaration_hashes(tmp_path):
    markup = script() + script(sri(b"wrong"), "app.js?v=2")
    result = check(*site(tmp_path, markup))
    assert [row["code"] for row in result["checks"]] == ["match", "integrity_mismatch"]
    assert result["cached_assets"] == 1 and result["asset_bytes_read"] == 3


def test_empty_asset_can_have_valid_integrity(tmp_path):
    result = check(*site(tmp_path, script(sri(b"")), {"app.js": b""}))
    assert result["status"] == "pass" and result["asset_bytes_read"] == 0


@pytest.mark.parametrize(
    "bound,reason", [("MAX_ASSET", "asset_size_limit"), ("MAX_TOTAL", "total_size_limit")]
)
def test_stream_growth_cannot_bypass_read_bounds(tmp_path, monkeypatch, bound, reason):
    site(tmp_path)
    path = tmp_path / "app.js"
    real_stat = Path.stat

    def understated(candidate, *args, **kwargs):
        info = real_stat(candidate, *args, **kwargs)
        if candidate == path:
            return SimpleNamespace(
                st_size=1, st_mtime_ns=info.st_mtime_ns, st_ctime_ns=info.st_ctime_ns
            )
        return info

    budget = {"read": 0}
    with monkeypatch.context() as scoped:
        scoped.setattr(core, bound, 2)
        scoped.setattr(Path, "stat", understated)
        with pytest.raises(InputError, match=reason):
            core.hashes(path, budget)
    assert budget["read"] == 3  # bounded one-byte overflow probe, including failed reads


def test_input_and_asset_errors(tmp_path):
    args = site(tmp_path)
    with pytest.raises(InputError, match="document_must_be_relative"):
        check(tmp_path, tmp_path / "index.html")
    with pytest.raises(InputError, match="unsafe_path"):
        check(tmp_path, Path("../index.html"))
    with pytest.raises(InputError, match="input_io_error"):
        check(tmp_path / "missing", Path("index.html"))
    with pytest.raises(InputError, match="invalid_root"):
        check(tmp_path / "index.html", Path("index.html"))
    (tmp_path / "index.html").write_bytes(b"\xff")
    with pytest.raises(InputError, match="html_not_utf8"):
        check(*args)
    (tmp_path / "index.html").write_bytes(b"")
    with pytest.raises(InputError, match="html_size_limit"):
        check(*args)
    args = site(tmp_path, script(url="missing.js"))
    assert code(check(*args)) == "asset_io_error"
    args = site(tmp_path, script(url="folder"))
    (tmp_path / "folder").mkdir()
    assert code(check(*args)) == "not_a_file"


def test_symlinks_fifos_and_reparse_attributes(tmp_path, monkeypatch):
    args = site(tmp_path)
    if os.name != "nt":
        (tmp_path / "link.js").symlink_to(tmp_path / "app.js")
        assert code(check(*site(tmp_path, script(url="link.js")))) == "linked_path"
        (tmp_path / "fifo").unlink(missing_ok=True)
        os.mkfifo(tmp_path / "fifo")
        assert code(check(*site(tmp_path, script(url="fifo")))) == "not_a_file"
        (tmp_path / "outside").symlink_to(tmp_path.parent, target_is_directory=True)
        assert code(check(*site(tmp_path, script(url="outside/secret")))) == "linked_path"
    site(tmp_path)
    actual = Path.lstat

    def marked(path, *args, **kwargs):
        info = actual(path, *args, **kwargs)
        if path.name == "app.js":
            return SimpleNamespace(st_mode=info.st_mode, st_file_attributes=0x400)
        return info

    with monkeypatch.context() as scoped:
        scoped.setattr(Path, "lstat", marked)
        assert code(check(*args)) == "linked_path"


def test_bounds_and_changed_asset_budget(tmp_path, monkeypatch):
    args = site(tmp_path)
    with monkeypatch.context() as scoped:
        scoped.setattr(core, "MAX_HTML", 1)
        with pytest.raises(InputError, match="html_size_limit"):
            check(*args)
    for name, limit, expected in (
        ("MAX_ASSET", 2, "asset_size_limit"),
        ("MAX_TOTAL", 2, "total_size_limit"),
    ):
        with monkeypatch.context() as scoped:
            scoped.setattr(core, name, limit)
            assert code(check(*args)) == expected
    with monkeypatch.context() as scoped:
        scoped.setattr(core, "MAX_TOKENS", 1)
        with pytest.raises(InputError, match="invalid_integrity"):
            metadata(sri() + " " + sri())
    with monkeypatch.context() as scoped:
        scoped.setattr(core, "MAX_ELEMENTS", 1)
        with pytest.raises(InputError, match="element_limit"):
            check(*site(tmp_path, script() * 2))
    args = site(tmp_path, script() + script(url="next.js"), {"app.js": b"abc", "next.js": b"abc"})
    original = Path.stat
    visits = 0

    def changing(path, *args, **kwargs):
        nonlocal visits
        info = original(path, *args, **kwargs)
        if path.name == "app.js" and "follow_symlinks" not in kwargs:
            visits += 1
            if visits >= 2:
                return SimpleNamespace(st_size=info.st_size, st_mtime_ns=0, st_ctime_ns=0)
        return info

    with monkeypatch.context() as scoped:
        scoped.setattr(core, "MAX_TOTAL", 3)
        scoped.setattr(Path, "stat", changing)
        result = check(*args)
    assert [row["code"] for row in result["checks"]] == ["changing_asset", "total_size_limit"]
    assert result["asset_bytes_read"] == 3


def test_cli_exit_codes_and_redaction(tmp_path, capsys):
    root, document = site(tmp_path)
    assert main([str(root), str(document), "--json"]) == 0
    assert json.loads(capsys.readouterr().out)["status"] == "pass"
    site(tmp_path, script(sri(b"wrong")))
    assert main([str(root), str(document)]) == 1
    assert "integrity_mismatch" in capsys.readouterr().out
    assert main([str(root), "private-filename.html", "--json"]) == 2
    output = capsys.readouterr().out
    assert "input_io_error" in output and "private-filename" not in output
    assert main([str(root), "private-filename.html"]) == 2
    assert "error:" in capsys.readouterr().out
